  for(const f of files){const u=URL.createObjectURL(f),v=document.createElement('video');pending.push({name:f.name,url:u});v.preload='metadata';const ready=waitEvent(v,'loadedmetadata');v.src=u;try{await ready;if(!Number.isFinite(v.duration)||v.duration<=0||v.duration>=86400)throw Error('请选择有效且小于 24 小时的视频');pending.at(-1).duration=v.duration}finally{v.removeAttribute('src');v.load()}}
